//! Count the struct fields visible past their module, per file.
//!
//! `adtb-structure ROOT...` prints `ROW PATH COUNT` for each `.rs` file under the roots
//! (skipping `target` directories) with a field declared `pub` (row `pub_fields`) or with a
//! restricted visibility other than `pub(self)` (row `crate_fields`). Named and tuple fields of
//! structs and unions count; fields generated by macros are not parsed and do not count. Exits
//! 1 and names the file when one does not parse.

use std::fs;
use std::io::Write;
use std::path::Path;
use std::process::ExitCode;

use syn::visit::Visit;
use syn::{Field, Visibility};

#[derive(Default)]
struct Counts {
    crate_fields: u32,
    pub_fields: u32,
}

impl<'ast> Visit<'ast> for Counts {
    fn visit_field(&mut self, field: &'ast Field) {
        match &field.vis {
            Visibility::Public(_) => self.pub_fields += 1,
            Visibility::Restricted(r) if !r.path.is_ident("self") => self.crate_fields += 1,
            _ => {}
        }
        syn::visit::visit_field(self, field);
    }
}

fn rust_files(dir: &Path, found: &mut Vec<String>) -> std::io::Result<()> {
    let mut entries: Vec<_> = fs::read_dir(dir)?.collect::<Result<_, _>>()?;
    entries.sort_by_key(fs::DirEntry::file_name);
    for entry in entries {
        let path = entry.path();
        if entry.file_type()?.is_dir() {
            if entry.file_name() != "target" {
                rust_files(&path, found)?;
            }
        } else if path.extension().is_some_and(|e| e == "rs") {
            found.push(path.to_string_lossy().into_owned());
        }
    }
    Ok(())
}

fn run(roots: &[String]) -> Result<(), String> {
    let mut files = Vec::new();
    for root in roots {
        rust_files(Path::new(root), &mut files).map_err(|e| format!("{root}: {e}"))?;
    }
    for file in files {
        let text = fs::read_to_string(&file).map_err(|e| format!("{file}: {e}"))?;
        let ast = syn::parse_file(&text).map_err(|e| format!("{file}: {e}"))?;
        let mut counts = Counts::default();
        counts.visit_file(&ast);
        let mut out = std::io::stdout().lock();
        for (row, n) in [
            ("crate_fields", counts.crate_fields),
            ("pub_fields", counts.pub_fields),
        ] {
            if n > 0 {
                writeln!(out, "{row} {file} {n}").map_err(|e| e.to_string())?;
            }
        }
    }
    Ok(())
}

fn main() -> ExitCode {
    let roots: Vec<String> = std::env::args().skip(1).collect();
    match run(&roots) {
        Ok(()) => ExitCode::SUCCESS,
        Err(message) => {
            writeln!(std::io::stderr(), "adtb-structure: {message}").unwrap_or_default();
            ExitCode::FAILURE
        }
    }
}
